import { useState } from 'react';

const LazyYoutube = ({ embedUrl, title, className = '' }) => {
  const [active, setActive] = useState(false);

  const videoIdMatch = embedUrl.match(/embed\/([^?&/]+)/);
  const videoId = videoIdMatch ? videoIdMatch[1] : null;
  const thumb = videoId
    ? `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`
    : null;

  if (active) {
    const src = `${embedUrl}${embedUrl.includes('?') ? '&' : '?'}autoplay=1&rel=0`;
    return (
      <iframe
        className={`video-frame ${className}`.trim()}
        title={title}
        src={src}
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
      />
    );
  }

  return (
    <button
      type="button"
      className={`lazy-youtube ${className}`.trim()}
      onClick={() => setActive(true)}
      aria-label={`Atskaņot video: ${title}`}
    >
      {thumb ? (
        <img src={thumb} alt="" loading="lazy" decoding="async" className="lazy-youtube-thumb" />
      ) : (
        <span className="lazy-youtube-fallback">Nospiest, lai ielādētu video</span>
      )}
      <span className="lazy-youtube-play" aria-hidden="true">
        ▶
      </span>
      <span className="lazy-youtube-note">Nospiest, lai ielādētu YouTube video (bez sīkdatnēm līdz klikšķim)</span>
    </button>
  );
};

export default LazyYoutube;
